using System;
using System.Drawing;

namespace Tachylite.Core.Models;

public abstract class PdfFormFieldElementModel
{
    public required string FieldName { get; set; }
    public required string WidgetKey { get; set; }
    public required Rectangle Bounds { get; set; }

    // Generated by OpenCode's Big Pickle: 1-based page that owns this widget. Reused field names can
    // have one model per page, so save needs the page to map each field back to the right model.
    public int PageNumber { get; set; }
}
